import { EbsVolumeDataGathererDto } from '../../microservices/ebsVolumeDataGatherer/dto/ebsVolumeDataGatherer.dto.js';
import { NodeUptimeDto } from '../../microservices/instanceUpTime/dto/instanceUptimeDTO.js';
