 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = parseFloat(this.topUpAmount);
    const threshold = parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD);
    return Number((topUpAmount * threshold).toFixed(2));
}

/**
 * Tops up the customer wallet back to the top up amount of the offering, if, and only if, the current wallet
 * balance has fallen below `topUpThreshold * topUpAmount`. The invoice which is generated for the top up stores
 * its payment as credit on the customer wallet.
 */
public async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.topUpAmount) {
        Offering.logger.log(
            `No top up amount configured for offering ${this.offeringId}, skipping the top up evaluation`,
        );
        return;
    }
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const topUpAmount = parseFloat(this.topUpAmount);
    const thresholdAmount = this.getTopUpThresholdAmount();
    const currentBalance = customer?.creditBalance ? parseFloat(customer?.creditBalance) : 0;
    const balance = isNaN(currentBalance) ? 0 : currentBalance;
    Offering.logger.log(
        `Evaluating top up for customer ${customerId}. Balance: ${balance}, threshold: ${thresholdAmount}, top up amount: ${topUpAmount}`,
    );
    if (balance >= thresholdAmount) {
        // A balance which is exactly at the threshold is considered to be sufficient.
        Offering.logger.log(
            `Customer ${customerId} has a sufficient balance of ${balance}, no top up invoice will be created`,
        );
        return;
    }
    const amountDue = Number((topUpAmount - balance).toFixed(2));
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountDue));
    Offering.logger.log(`Creating top up invoice for customer ${customerId} for ${amountDue}`);
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

/**
 * Calculates the total dollar amount of the usage a customer has accrued between two dates.
 */
public async calculateUsageTotal({
    customer,
    startDate,
    endDate,
}: {
    customer?: ReadCustomerResponseData;
    startDate: Date;
    endDate: Date;
}): Promise<number> {
    const lineItems = await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId: customer?.customerId ? customer?.customerId : this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    return Number(lineItems.getTotal().toFixed(2));
}

/**
 * Deducts the usage which has been accrued since the last top up check from the customer wallet, and then
 * evaluates if the wallet must be topped up. Usage is always deducted in full, even when the deduction takes the
 * wallet balance below zero. No usage invoice is created, the usage is exclusively paid for with prepaid credit.
 */
public async processTopUp({
    customer,
    creditService,
    startDate,
    endDate,
}: {
    customer?: ReadCustomerResponseData;
    creditService?: CreditService;
    startDate?: Date;
    endDate?: Date;
}): Promise<string | void> {
    const creditServiceToUse = creditService ? creditService : this.creditService;
    const usageEndDate = endDate ? endDate : new Date();
    const usageStartDate = startDate ? startDate : DatetimeUtils.oneHourAgo(usageEndDate);
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const usageTotal = await this.calculateUsageTotal({
        customer,
        startDate: usageStartDate,
        endDate: usageEndDate,
    });
    const currentBalance = customer?.creditBalance ? parseFloat(customer?.creditBalance) : 0;
    let balance = isNaN(currentBalance) ? 0 : currentBalance;
    Offering.logger.log(
        `Processing top up for customer ${customerId}. Usage total: ${usageTotal}, current balance: ${balance}`,
    );
    if (usageTotal > 0) {
        if (!creditServiceToUse) {
            throw new Error('A credit service is required in order to deduct usage from a customer wallet');
        }
        const allowNegativeBalance = true;
        await creditServiceToUse.create(
            {
                transactionAmount: (usageTotal * -1).toFixed(2),
                customerId,
                businessID: this.businessID,
                timestamp: usageEndDate.toISOString(),
                metadata: {
                    offeringId: this.offeringId,
                    reason: `Usage for ${this.offeringName}`,
                },
            },
            false,
            allowNegativeBalance,
        );
        balance = Number((balance - usageTotal).toFixed(2));
        if (customer) {
            customer.creditBalance = balance.toString();
        }
    }
    return this.topUp({ customer });
}

