import { IsNotEmpty, IsString } from 'class-validator';

export class OfferingTopUpCheckerDto {
    /**
     *
     * Static string indicating the dimensionType
     */
    @IsString()
    @IsNotEmpty()
    public dimensionType: 'offeringTopUpChecker';

    /**
     * The unique identifier of the offering which the top up check is run for
     */
    @IsString()
    @IsNotEmpty()
    public offeringId: string;

    /**
     * The unique identifier for the SaaS business
     */
    @IsString()
    @IsNotEmpty()
    public businessID: string;
}

import { Job } from 'bull';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { OnQueueFailed, Process, Processor } from '@nestjs/bull';
import { Inject, Logger, forwardRef } from '@nestjs/common';
import { serializeError } from 'serialize-error';
import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { OfferingTopUpCheckerDto } from './dto/offeringTopUpChecker.dto.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { DatetimeUtils } from '../../utils/datetime.js';

@Processor('scheduler_queue')
export class OfferingTopUpChecker {
    private static readonly logger = new Logger(OfferingTopUpChecker.name);
    constructor(
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
        @Inject(forwardRef(() => CreditService)) readonly creditService: CreditService,
    ) {}

    /**
     * Runs on an hourly basis for every offering which has a `topUp` billing cycle.
     * For every customer enrolled in the offering, the usage which was accrued in the last hour is deducted from the
     * customer wallet, and the wallet is topped up when the balance has fallen below the top up threshold.
     */
    @Process('offeringTopUpChecker')
    async evaluateTopUps({ data: { scheduleParameters, subject } }: Job<SchedulerEntity>) {
        const { businessID, offeringId } = scheduleParameters as OfferingTopUpCheckerDto;
        OfferingTopUpChecker.logger.log(
            `Starting top up checker for offering: ${offeringId}, businessID: ${businessID}, subject: ${subject}`,
        );
        const endDate = new Date();
        const startDate = DatetimeUtils.oneHourAgo(endDate);
        const { data } = await this.customerService.findAllCustomersWithOfferingId({ businessID, offeringId });
        await Promise.all(
            (data ? data : []).map(async (customer: ReadCustomerResponseData) => {
                try {
                    await this.topUpCustomer({ customer, businessID, offeringId, startDate, endDate });
                } catch (error) {
                    OfferingTopUpChecker.logger.error(serializeError(error));
                    AuditService.publishEvent({
                        message: 'Failed to top up customer wallet',
                        topic: AuditScope.ERROR,
                        data: [
                            {
                                error: serializeError(error),
                                customerId: customer?.customerId,
                                businessID,
                                offeringId,
                            },
                        ],
                    });
                }
            }),
        );
        OfferingTopUpChecker.logger.log(`Finished top up checker for offering: ${offeringId}`);
    }

    private async topUpCustomer({
        customer,
        businessID,
        offeringId,
        startDate,
        endDate,
    }: {
        customer: ReadCustomerResponseData;
        businessID: string;
        offeringId: string;
        startDate: Date;
        endDate: Date;
    }): Promise<string | void> {
        const { customerId } = customer;
        const { offering } = await this.contractService.findOne({
            businessID,
            customerId,
            offeringId,
            offeringEnrollmentDate: customer?.offeringEnrollmentDate,
            freeTrialEndDate: customer?.freeTrialEndDate,
        });
        offering.creditService = this.creditService;
        return offering.processTopUp({ customer, creditService: this.creditService, startDate, endDate });
    }

    @OnQueueFailed({ name: 'offeringTopUpChecker' })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to evaluate top ups for customers',
            data: [job],
            topic: AuditScope.ERROR,
        });
    }

    /**
     * Top up schedulers are offering level, there is exactly one scheduler for each top up offering.
     */
    static getTopUpSchedulerId(offeringId: string): string {
        return Offering.getTopUpSchedulerID({ offeringId });
    }
}

