import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { InvoiceLineItem } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { SupportedMeasurementFrequencies } from '../../scheduler/dto/scheduler.dto.js';
import { CreditService } from '../../credit/credit.service.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

describe('Top up offerings', () => {
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeOfferingId = 'fakeOfferingId';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
    const sharedDimensionId = 'fakeDimensionId';
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let creditService: CreditService;
    let topUpOffering: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({ invoiceId: '123', message: 'foobar' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ data: [] }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({ message: 'foobar' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'emitOne').mockImplementation(async () => ({}));
    });

    beforeEach(() => {
        topUpOffering = {
            offeringId: fakeOfferingId,
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            topUpThreshold: '0.2',
            dimensions: [
                {
                    aggregationInterval: aggregationInterval.day,
                    aggregationMethod: aggregationMethod.sum,
                    dimensionId: sharedDimensionId,
                    dimensionName: 'fakeDimensionName',
                    consumptionPrice: '1',
                    rounding: roundingEnum.ceiling,
                    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
                    usageIncrement: '1',
                },
            ],
        };
        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
            creditBalance: '100',
            offering: topUpOffering,
        };
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    afterAll(() => {
        jest.resetAllMocks();
    });

    const getOffering = (overrides: Partial<ReadOfferingResponseData> = {}) =>
        Offering.getInstance(
            { ...topUpOffering, ...overrides },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        );

    const mockUsage = (value: string) =>
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId: sharedDimensionId,
                            usage: [{ startTime: new Date().toISOString(), endTime: new Date().toISOString(), value }],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );

    test('Top up offerings must register a single hourly offering level scheduler', async () => {
        const offering = getOffering();
        await offering.enroll('fakeSubject', customer);
        expect(schedulerService.create).toBeCalledTimes(1);
        expect(schedulerService.create).toBeCalledWith(
            expect.objectContaining({
                rate: SupportedMeasurementFrequencies.everyHour,
                schedulerID: Offering.getTopUpSchedulerID({ offeringId: fakeOfferingId }),
                businessID: fakeBusinessID,
                scheduleParameters: expect.objectContaining({
                    businessID: fakeBusinessID,
                    offeringId: fakeOfferingId,
                }),
            }),
        );
        // The scheduler must not be customer specific
        expect(schedulerService.create.mock.calls[0][0].schedulerID).not.toContain(fakeCustomerID);
        const secondOffering = Offering.getInstance(
            topUpOffering,
            'someOtherCustomer',
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
        );
        await secondOffering.enroll('fakeSubject', { ...customer, customerId: 'someOtherCustomer' });
        expect(schedulerService.create.mock.calls[1][0].schedulerID).toEqual(
            schedulerService.create.mock.calls[0][0].schedulerID,
        );
    });

    test('Enrollment must top up the wallet when the balance is below the threshold', async () => {
        const offering = getOffering();
        await offering.enroll('fakeSubject', { ...customer, creditBalance: '10' });
        expect(invoicesService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledWith(
            expect.objectContaining({
                businessID: fakeBusinessID,
                customerId: fakeCustomerID,
                storePaymentAsCredit: true,
            }),
        );
        //eslint-disable-next-line
        //@ts-ignore
        expect(invoicesService.create.mock.calls[0][0].items.getLineItems()).toEqual([
            expect.objectContaining(new InvoiceLineItem('foobar - Top Up', 1, 90)),
        ]);
    });

    test('Enrollment must not top up the wallet when the balance is exactly at the threshold', async () => {
        const offering = getOffering();
        await offering.enroll('fakeSubject', { ...customer, creditBalance: '20' });
        expect(schedulerService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('Top up must not create an invoice when the balance is above the threshold', async () => {
        const offering = getOffering();
        await offering.topUp({ customer });
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('Top up must respect a custom threshold', async () => {
        const offering = getOffering({ topUpThreshold: '0.5' });
        await offering.topUp({ customer: { ...customer, creditBalance: '49.50' } });
        expect(invoicesService.create).toBeCalledTimes(1);
        //eslint-disable-next-line
        //@ts-ignore
        expect(invoicesService.create.mock.calls[0][0].items.getLineItems()).toEqual([
            expect.objectContaining(new InvoiceLineItem('foobar - Top Up', 1, 50.5)),
        ]);
    });

    test('Top up must default the threshold to 20% of the top up amount', async () => {
        const offering = getOffering({ topUpThreshold: undefined });
        expect(offering.topUpThreshold).toEqual('0.2');
        await offering.topUp({ customer: { ...customer, creditBalance: '20.01' } });
        expect(invoicesService.create).toBeCalledTimes(0);
        await offering.topUp({ customer: { ...customer, creditBalance: '19.99' } });
        expect(invoicesService.create).toBeCalledTimes(1);
    });

    test('Hourly checks must deduct the usage from the wallet and top up with the updated balance', async () => {
        mockUsage('90');
        const offering = getOffering();
        const walletCustomer = { ...customer, creditBalance: '100' };
        await offering.processTopUp({ customer: walletCustomer, creditService });
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({
                transactionAmount: '-90.00',
                customerId: fakeCustomerID,
                businessID: fakeBusinessID,
            }),
            false,
            true,
        );
        expect(walletCustomer.creditBalance).toEqual('10');
        // The balance of 10 is below the threshold of 20, therefore the wallet is topped back up to 100
        expect(invoicesService.create).toBeCalledTimes(1);
        //eslint-disable-next-line
        //@ts-ignore
        expect(invoicesService.create.mock.calls[0][0].items.getLineItems()).toEqual([
            expect.objectContaining(new InvoiceLineItem('foobar - Top Up', 1, 90)),
        ]);
    });

    test('Hourly checks must deduct usage which exceeds the current balance in full', async () => {
        mockUsage('150');
        const offering = getOffering();
        const walletCustomer = { ...customer, creditBalance: '100' };
        await offering.processTopUp({ customer: walletCustomer, creditService });
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({ transactionAmount: '-150.00' }),
            false,
            true,
        );
        expect(walletCustomer.creditBalance).toEqual('-50');
        //eslint-disable-next-line
        //@ts-ignore
        expect(invoicesService.create.mock.calls[0][0].items.getLineItems()).toEqual([
            expect.objectContaining(new InvoiceLineItem('foobar - Top Up', 1, 150)),
        ]);
    });

    test('Hourly checks must not create a wallet transaction when there is no usage', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ data: [] }));
        const offering = getOffering();
        await offering.processTopUp({ customer: { ...customer, creditBalance: '10' }, creditService });
        expect(creditService.create).toBeCalledTimes(0);
        expect(invoicesService.create).toBeCalledTimes(1);
    });

    test('Process billing for a top up offering must not create a usage invoice', async () => {
        mockUsage('5');
        const offering = getOffering();
        await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '100' });
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({ transactionAmount: '-5.00' }),
            false,
            true,
        );
        // The balance after the deduction is 95, which is above the threshold, therefore no invoice is created at all
        expect(invoicesService.create).toBeCalledTimes(0);
    });
});

