import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { Job } from 'bull';
import { OfferingTopUpChecker } from './offeringTopUpChecker.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { Offering } from '../../offering/entities/offeringPackage.entity.js';

describe('OfferingTopUpChecker', () => {
    const businessID = 'fakeBusinessID';
    const customerId = 'fakeCustomerID';
    const offeringId = 'fakeOfferingId';
    let checker: OfferingTopUpChecker;
    let customerService: CustomerService;
    let contractService: ContractService;
    let creditService: CreditService;
    let processTopUp: jest.Mock;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [OfferingTopUpChecker],
        })
            .useMocker(createMock)
            .compile();

        checker = module.get<OfferingTopUpChecker>(OfferingTopUpChecker);
        customerService = module.get<CustomerService>(CustomerService);
        contractService = module.get<ContractService>(ContractService);
        creditService = module.get<CreditService>(CreditService);
        processTopUp = jest.fn();
        jest.spyOn(customerService, 'findAllCustomersWithOfferingId').mockResolvedValue({
            //eslint-disable-next-line
            //@ts-ignore
            data: [{ customerId, businessID, creditBalance: '10' }],
            message: 'Found Customers',
        });
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(contractService, 'findOne').mockResolvedValue({
            offering: { processTopUp } as unknown as Offering,
            customerId,
            offeringId,
            offeringEnrollmentDate: new Date().toISOString(),
        });
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(checker).toBeDefined();
    });

    it('should evaluate the top up of every customer enrolled in the offering', async () => {
        await checker.evaluateTopUps({
            data: { scheduleParameters: { businessID, offeringId, dimensionType: 'offeringTopUpChecker' } },
        } as unknown as Job<SchedulerEntity>);
        expect(customerService.findAllCustomersWithOfferingId).toBeCalledWith({ businessID, offeringId });
        expect(contractService.findOne).toBeCalledWith(expect.objectContaining({ businessID, customerId, offeringId }));
        expect(processTopUp).toBeCalledTimes(1);
        expect(processTopUp).toBeCalledWith(
            expect.objectContaining({
                customer: expect.objectContaining({ customerId }),
                creditService,
                startDate: expect.any(Date),
                endDate: expect.any(Date),
            }),
        );
    });

    it('should use a single stable offering level scheduler id', () => {
        expect(OfferingTopUpChecker.getTopUpSchedulerId(offeringId)).toEqual(
            Offering.getTopUpSchedulerID({ offeringId }),
        );
        expect(OfferingTopUpChecker.getTopUpSchedulerId(offeringId)).toContain(offeringId);
        expect(OfferingTopUpChecker.getTopUpSchedulerId(offeringId)).not.toContain(customerId);
    });
});

